export function pnoV18ResolveOpenArgs(row, type = "no_entry", page = 1, options = {}) {
  const sourceRow = row && typeof row === "object" && !Array.isArray(row) ? row : null;
  const rawType = String(type || "no_entry").trim();
  return {
    row: sourceRow,
    proofId: String(sourceRow?.proofId || "").trim(),
    day: String(sourceRow?.pnoSourceDay || "").trim(),
    type: ["total", "already", "no_entry"].includes(rawType) ? rawType : "no_entry",
    page: Math.max(1, Number(page) || 1),
    force: options?.force === true,
  };
}

